/* Documentation views, state scenarios, and final interaction wiring. */
'use strict';
AC.catalog=[
['Member access',[['sign-in','Email sign-in','Email validation and a simulated magic-link handoff.'],['verification-pending','Verification pending','Education details, review request, and access boundary.'],['claim','Claim a profile','Private identification link with identity verification.'],['remove','Public profile removal','One action; no account needed; suppression retained.']]],
['Discover',[['index','Discover','Relevant people, search, and relationship shortcuts.'],['search','Search & filters','Natural-language queries, 17 industries, 66 specialties, radius, year, openness, confirmed-only, and breakdowns.'],['profile','Alumni profile','Experience, education, labeled AI summary, privacy, notes, provenance, and saving.'],['recommendations','Who to meet','Goal-dependent ordering with a reason for every suggestion.']]],
['Profile & privacy',[['edit-profile','Edit your profile','Professional details, education, and openness.'],['settings','Contact visibility','Independent privacy choices per contact detail.'],['data-sources','Data sources','Field-level provenance and correction paths.']]],
['Relationships',[['relationships','Relationship overview','Saved people, private interaction log, and reminders.'],['saved','Saved contacts','Private, searchable saved contacts.'],['lists','Private lists','Create lists and choose saved contacts.'],['followups','Follow-up reminders','Add reminders and mark them complete.'],['introductions','Request introduction','Ask a shared connection for an opt-in introduction.'],['introduction-review','Connector decision','First consent gate; agree or decline.'],['introduction-response','Recipient decision','Second consent gate; accept or decline.']]],
['Trips',[['trips','Trips overview','Upcoming visit and shortlist entry.'],['trip-planner','Plan a visit','Destination, dates, industry, and goal.'],['trip-shortlist','Meeting shortlist','Select relevant people, then review each invitation.'],['outreach','Editable outreach','AI-labeled drafts, relay explanation, review-before-send.'],['meeting','Calendar invitation','Time zone, duration, location, and .ics download.']]],
['Insights & future concepts',[['insights','Network insights','Confirmed/unconfirmed counts by industry and market; estimates separate.'],['mentorship','Mentorship concept','Matching by advice needed, market, and mentoring openness.'],['businesses','Business directory concept','Fictional alumni businesses and member connections.'],['events','City events concept','City filtering and local RSVP state.'],['jobs','Jobs & referrals concept','Fictional roles and editable referral requests.']]],
['Administration',[['admin-import','Roster import','CSV staging, validation, duplicates, suppression, and review.'],['admin-review','Profile review','Review fields without confirming identity.'],['admin-verification','Verification queue','Evidence review, approval, more information, or decline.'],['admin-removal','Removal exceptions','Support-assisted removal and suppression register.'],['admin-audit','Audit history','Locally recorded administrative actions.']]]
];
AC.stateScreens=['index','search','recommendations','relationships','saved','lists','followups','trips','trip-shortlist','insights','admin-review','admin-verification','admin-removal','admin-audit','mentorship','businesses','events','jobs'];
AC.renders.catalog=()=>`${AC.title('The Alumni Connect prototype library.','Every screen uses the same responsive system. Open any page at 375px or a wide desktop width.',AC.link('components','View components','btn primary'),'Design handoff / Screen directory')}<div class="notice" style="margin-bottom:32px">${AC.icon('info')}<div><strong>Fictional data. Real interaction paths.</strong><p>All sending, identity checks, and admin permissions are simulated. Theme selection applies across screens. State links below are documentation controls, separate from the product UI.</p></div></div>${AC.catalog.map(([group,items])=>`<section style="margin-top:32px"><div class="section-head"><h2>${group}</h2><span class="meta">${items.length} screens</span></div><div class="catalog-grid">${items.map(([id,title,desc])=>`<div class="catalog-item"><h3>${AC.link(id,title,'')}</h3><p>${desc}</p><div class="state-links">${AC.link(id,'Default','')}${AC.stateScreens.includes(id)?['loading','empty','error'].map(state=>AC.link(id,state[0].toUpperCase()+state.slice(1),'','?state='+state)).join(''):''}</div></div>`).join('')}</div></section>`).join('')}<section class="panel pad" style="margin-top:40px"><h2>Walk through the consent sequence</h2><ol style="padding-left:20px"><li>Request an introduction on the requester screen.</li><li>Open the connector decision screen and agree.</li><li>Open the recipient decision screen and accept.</li><li>Return to the requester screen to see the completed introduction.</li></ol><div class="form-actions">${AC.link('introductions','1. Request','btn')}${AC.link('introduction-review','2. Connector','btn')}${AC.link('introduction-response','3. Recipient','btn')}</div></section><p class="footnote">See DESIGN.md for decisions, implementation boundaries, screen coverage, and recommendations.</p>`;
AC.renders.components=()=>`${AC.title('One system. Every point of trust.','Reusable components for a private, professional alumni network.',AC.link('catalog','Browse screen prototypes','btn'),'Design system / Component previews')}<div class="stack"><section class="panel pad"><h2>Typography & hierarchy</h2><div class="eyebrow accent" style="margin-top:24px">A Wisconsin beginning.</div><p class="serif" style="font-size:var(--text-display);margin:8px 0 16px">Connections that mean something.</p><p style="max-width:68ch">Geist carries the interface with readable, specific language. Source Serif 4 adds warmth to moments of discovery without competing with dense professional information.</p><p class="meta mono" style="margin-top:16px">Small metadata uses Geist Mono sparingly for dates, labels, and counts.</p></section><section class="panel pad"><h2>Action hierarchy</h2><div class="od-cluster" style="margin-top:24px">${AC.btn('Primary action','component-feedback','primary')}${AC.btn('Secondary action','component-feedback')}${AC.btn('Text action '+AC.icon('arrow'),'component-feedback','quiet')}${AC.btn('Disabled','component-feedback','','disabled')}${AC.btn('Remove profile','component-feedback','danger')}</div><p class="meta" style="margin-top:16px">Tab through to see focus. Hover, pressed, and disabled states share the token contract.</p></section><section class="panel pad"><h2>Status has a label</h2><div class="od-cluster" style="margin-top:24px">${AC.badge({confirmed:true})}${AC.badge({confirmed:false})}<span class="chip">${AC.icon('clock')}Verification pending</span><span class="chip ai">AI-generated summary</span><span class="chip ai">AI-drafted · Editable</span></div><p class="small muted" style="margin-top:20px">Confirmed describes claimed identity. Unconfirmed is an ordinary pre-claim state, never an error treatment. AI is labeled separately from source reliability.</p></section><section class="panel pad"><h2>Contact visibility</h2><div class="form-grid" style="margin-top:24px">${['All verified members','Connections only','Hidden from everyone'].map((t,i)=>`<div class="panel pad"><h3>${AC.icon('lock')} ${t}</h3><p class="small muted" style="margin-top:12px">${AC.visibilityCopy(['members','connections','hidden'][i])}</p></div>`).join('')}</div></section><section class="panel pad"><h2>Form feedback</h2><div class="form-grid" style="margin-top:24px">${AC.field('Email address','component-email','alex.morgan@example.com','email','Visible label and specific helper text.')}<div class="field"><label for="component-invalid">Class year</label><input id="component-invalid" value="08" aria-invalid="true" aria-describedby="component-error"><span class="error-text" id="component-error">Enter a four-digit year, such as 2008.</span></div></div><div class="stack" style="margin-top:24px">${AC.notice('Your settings have been saved. Only verified members can see this detail.','success')}${AC.notice('We couldn’t load the roster. Your staged import has been kept. Try again.','error')}</div></section><section class="panel"><div class="pad"><h2>Member row</h2><p class="meta" style="margin-top:8px">Long-name and missing-data examples are included in search.</p></div>${AC.person(AC.byId('p1'))}${AC.person(AC.byId('p8'))}</section><section class="panel"><div class="pad"><h2>Loading</h2></div>${AC.skeleton()}</section><section class="panel">${AC.empty('No conversations saved yet','Find an alumnus you’d like to know, then save their profile to keep the connection close.',AC.link('search','Find alumni','btn primary'))}</section><section class="panel pad"><h2>Theme & motion</h2><p class="small muted" style="margin-top:16px">The sun control in the header toggles themes. The first visit follows the operating system. Reduced-motion preferences disable transitions. No animation is needed to understand a state.</p></section></div>`;
AC.handlers['component-feedback']=()=>AC.toast('Component action activated');
// Apply stored mutations to the dataset before any screen renders.
AC.people.push(...(AC.state.imported||[]));
Object.entries(AC.state.profileOverrides||{}).forEach(([id,fields])=>Object.assign(AC.byId(id),fields));
(AC.state.confirmedIds||[]).forEach(id=>{const p=AC.people.find(x=>x.id===id);if(p)p.confirmed=true});
// Keep navigation functional inside sandboxed previews; file links remain usable independently.
AC.rootURL=new URL(AC.base||'./',location.href);
AC.url=(page='index',query='')=>new URL(page==='index'?'index.html':'screens/'+page+'.html',AC.rootURL).href+query;
AC.viewMemory={};
AC.go=(page,query='',remember=true)=>{if(remember)AC.viewMemory[AC.screen]={params:AC.params.toString(),scroll:window.scrollY};AC.screen=page;let old=AC.viewMemory[page];AC.params=new URLSearchParams(query?query.replace(/^\?/,''):(old?.params||''));document.title=(AC.catalog.flatMap(g=>g[1]).find(x=>x[0]===page)?.[1]||'Alumni Connect')+' · Alumni Connect';AC.render();let main=document.getElementById('main');if(main)main.focus({preventScroll:true});window.scrollTo({top:old?.scroll||0,behavior:'instant'})};
document.addEventListener('click',e=>{if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.shiftKey)return;let a=e.target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download'))return;let u;try{u=new URL(a.href)}catch{return}if(!u.href.startsWith(AC.rootURL.href))return;let page=u.pathname.endsWith('/index.html')?'index':u.pathname.match(/\/screens\/([^/]+)\.html$/)?.[1];if(page&&AC.renders[page]){e.preventDefault();AC.go(page,u.search)}});
AC.originalStateBlock=AC.stateBlock;
AC.afterRender=()=>{
 if(AC.screen==='recommendations')AC.rank();
 if(AC.screen==='insights')AC.insights();
 if(AC.screen==='search'&&AC.state.searchFilters){const f=AC.state.searchFilters;Object.entries(f).forEach(([id,value])=>{let el=document.getElementById(id);if(el){if(el.type==='checkbox')el.checked=value;else el.value=value}});AC.search()}
 if(AC.screen==='mentorship'){let el=document.getElementById('mentor-results');el.innerHTML=AC.stateBlock(el.innerHTML,'No mentors match yet','Try another market or advice topic.')}
 if(['businesses','events','jobs'].includes(AC.screen)){let id={businesses:'business-results',events:'event-results',jobs:'job-results'}[AC.screen],el=document.getElementById(id);el.innerHTML=AC.stateBlock(el.innerHTML,'No matches yet','Broaden your search or return later.')}
 // Declare validation descriptions once, matching each actual feedback node.
 document.querySelectorAll('input[id]').forEach(el=>{let feedback=document.getElementById(el.id+'-error');if(feedback)el.setAttribute('aria-describedby',feedback.id)});
};
const searchOriginal=AC.search;
AC.search=()=>{searchOriginal();if(AC.screen!=='search')return;AC.state.searchFilters={};['industry','metro','radius','class-year','specialty','open-to','confirmed-only','result-sort'].forEach(id=>{let el=document.getElementById(id);if(el)AC.state.searchFilters[id]=el.type==='checkbox'?el.checked:el.value});AC.persist()};
// Set saved filters before the search's first render call, so they are not overwritten.
const renderOriginal=AC.renders.search;
AC.renders.search=()=>{let html=renderOriginal(),f=AC.state.searchFilters;AC.pendingSearchFilters=f?{...f}:null;return html};
const afterOriginal=AC.afterRender;
AC.afterRender=()=>{if(AC.screen==='search'&&AC.pendingSearchFilters)AC.state.searchFilters=AC.pendingSearchFilters;afterOriginal()};
AC.onChange=e=>{let id=e.target.id;if(AC.screen==='recommendations'&&['recommend-goal','recommend-city'].includes(id))AC.rank();if(AC.screen==='insights'&&id.startsWith('insight-'))AC.insights();if(id.startsWith('privacy-')&&!id.startsWith('privacy-help-')){let key=id.replace('privacy-',''),help=document.getElementById('privacy-help-'+key);if(help)help.textContent=AC.visibilityCopy(e.target.value)}if(AC.screen==='mentorship'&&['mentor-topic','mentor-city'].includes(id))AC.handlers['match-mentors']();if(id==='event-city'){AC.params.delete('state');document.getElementById('event-results').innerHTML=AC.eventCards(AC.events.filter(x=>e.target.value==='All cities'||x.city===e.target.value))}if(id==='business-industry')AC.filterBusinesses();if(id==='job-industry')AC.filterJobs()};
AC.filterBusinesses=()=>{AC.params.delete('state');let q=document.getElementById('business-search').value.toLowerCase(),industry=document.getElementById('business-industry').value;document.getElementById('business-results').innerHTML=AC.businessCards(AC.businesses.filter(b=>(industry==='All industries'||industry===b.field)&&(b.name+' '+b.copy+' '+b.city).toLowerCase().includes(q)))};
AC.filterJobs=()=>{AC.params.delete('state');let q=document.getElementById('job-search').value.toLowerCase(),industry=document.getElementById('job-industry').value;document.getElementById('job-results').innerHTML=AC.jobCards(AC.jobs.filter(j=>(industry==='All industries'||industry===j.industry)&&(j.title+' '+j.company+' '+j.city).toLowerCase().includes(q)))};
document.addEventListener('input',e=>{if(e.target.id==='saved-search')document.getElementById('saved-list').innerHTML=AC.savedList();if(e.target.id==='business-search')AC.filterBusinesses();if(e.target.id==='job-search')AC.filterJobs()});
AC.onKey=e=>{let mapping={'signin-email':'send-link','claim-email':'claim-profile','list-name':'create-list','reminder-title':'save-reminder'};if(e.key==='Enter'&&!e.shiftKey&&mapping[e.target.id]){e.preventDefault();let action=mapping[e.target.id];let b=document.querySelector(`[data-action="${action}"]`);if(b)AC.handlers[action](b)}};
document.addEventListener('focusout',e=>{if(e.target.id==='signin-email'){const el=e.target,err=document.getElementById('signin-email-error');if(!err)return;let invalid=el.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(el.value);err.hidden=!invalid;err.textContent=invalid?'Enter a complete email address, such as alex@example.com.':'';el.setAttribute('aria-invalid',String(!!invalid))}});
// Preserve visible focus when a local mutation rebuilds a view.
const renderWithFocus=AC.render;
AC.render=()=>{let active=document.activeElement,identity=active?.dataset?.action?{action:active.dataset.action,id:active.dataset.id,index:active.dataset.index}:null,elementId=active?.id;renderWithFocus();if(identity){let replacement=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===identity.action&&el.dataset.id===identity.id&&el.dataset.index===identity.index);(replacement||document.getElementById('main'))?.focus({preventScroll:true})}else if(elementId){document.getElementById(elementId)?.focus({preventScroll:true})}};
// A new natural-language search starts a new set of filters; returning to search retains them.
AC.handlers['home-search']=()=>{let q=document.getElementById('discovery-search').value;AC.state.searchFilters=null;delete AC.viewMemory.search;AC.go('search','?q='+encodeURIComponent(q))};
AC.handlers['suggest-search']=b=>{AC.state.searchFilters=null;delete AC.viewMemory.search;AC.go('search','?q='+encodeURIComponent(b.dataset.query))};
const insightsWithExplore=AC.insights;
AC.insights=()=>{insightsWithExplore();let container=document.getElementById('insight-content');if(AC.params.get('state'))return;container.insertAdjacentHTML('beforeend',`<section class="panel pad" style="margin-top:24px"><div class="section-head"><div><h2>More ways to connect</h2><p class="small muted">Explore upcoming features in the alumni network.</p></div></div><div class="od-cluster">${AC.link('mentorship','Mentorship','btn')}${AC.link('businesses','Alumni businesses','btn')}${AC.link('events','City events','btn')}${AC.link('jobs','Jobs & referrals','btn')}</div></section>`)};
